import{_ as i,c as s,o as e,a3 as t}from"./chunks/framework.BusRvirq.js";const k=JSON.parse('{"title":"5분 퀵스타트 가이드","description":"SyncETA 로컬 환경 구동, 첫 번째 시나리오 녹화, Playwright 기반 테스트 실행 및 결과 확인까지 5분 만에 완료하는 실습 가이드입니다.","frontmatter":{"title":"5분 퀵스타트 가이드","description":"SyncETA 로컬 환경 구동, 첫 번째 시나리오 녹화, Playwright 기반 테스트 실행 및 결과 확인까지 5분 만에 완료하는 실습 가이드입니다.","head":[["meta",{"name":"keywords","content":"SyncETA 퀵스타트, 테스트 자동화 시작하기, Playwright 테스트, 녹화 및 실행, Docker 배포"}],["meta",{"property":"og:title","content":"5분 퀵스타트 가이드 | SyncETA"}],["meta",{"property":"og:description","content":"SyncETA를 사용하여 5분 만에 첫 번째 테스트 시나리오를 녹화하고 실행하는 방법을 안내합니다."}],["link",{"rel":"canonical","href":"https://doc.empasy.com/synceta/quickstart.html"}]],"sort":30},"headers":[],"relativePath":"synceta/quickstart.md","filePath":"ko/synceta/quickstart.md","lastUpdated":1787441310000}'),l={name:"synceta/quickstart.md"};function n(r,a,o,h,c,d){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="_5분-퀵스타트-가이드" tabindex="-1">5분 퀵스타트 가이드 <a class="header-anchor" href="#_5분-퀵스타트-가이드" aria-label="Permalink to “5분 퀵스타트 가이드”">​</a></h1><p>본 가이드는 SyncETA를 로컬 또는 개발 환경에 구동하고, 대상 웹사이트에 대한 첫 번째 테스트 시나리오를 녹화하여 실행하는 전체 과정을 안내합니다.</p><hr><h2 id="_1-사전-요구사항-확인" tabindex="-1">1. 사전 요구사항 확인 <a class="header-anchor" href="#_1-사전-요구사항-확인" aria-label="Permalink to “1. 사전 요구사항 확인”">​</a></h2><ul><li><strong>운영체제</strong>: Windows 10/11, macOS (Apple Silicon/Intel), Linux (Ubuntu 20.04+)</li><li><strong>필수 런타임</strong>: Node.js 20+ 또는 Docker Compose</li><li><strong>권장 브라우저</strong>: Google Chrome 최신 버전</li></ul><hr><h2 id="_2-시스템-구동-docker-compose-기준" tabindex="-1">2. 시스템 구동 (Docker Compose 기준) <a class="header-anchor" href="#_2-시스템-구동-docker-compose-기준" aria-label="Permalink to “2. 시스템 구동 (Docker Compose 기준)”">​</a></h2><p>아래 명령어를 통해 SyncETA 코어 서버, MCP 서비스 및 데이터베이스를 한 번에 구동합니다.</p><div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 저장소 클론 및 디렉토리 이동</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/DramaticCollaboration/SyncSeries.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SyncSeries/SyncEta</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 컨테이너 서비스 일괄 실행</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.dev.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>서비스가 정상적으로 기동되면 브라우저에서 <code>http://localhost:9000</code>으로 접속하여 SyncETA 콘솔에 로그인합니다.</p><hr><h2 id="_3-첫-번째-시나리오-녹화-및-실행-4단계-실습" tabindex="-1">3. 첫 번째 시나리오 녹화 및 실행 (4단계 실습) <a class="header-anchor" href="#_3-첫-번째-시나리오-녹화-및-실행-4단계-실습" aria-label="Permalink to “3. 첫 번째 시나리오 녹화 및 실행 (4단계 실습)”">​</a></h2><h3 id="_1단계-프로젝트-생성-및-대상-url-지정" tabindex="-1">1단계: 프로젝트 생성 및 대상 URL 지정 <a class="header-anchor" href="#_1단계-프로젝트-생성-및-대상-url-지정" aria-label="Permalink to “1단계: 프로젝트 생성 및 대상 URL 지정”">​</a></h3><ol><li>대시보드 좌측 메뉴에서 <strong>&#39;프로젝트&#39;</strong>를 클릭합니다.</li><li>우측 상단의 <strong>&#39;새로운 프로젝트&#39;</strong>를 선택하고, 프로젝트 이름(예: <code>쇼핑몰 E2E 검증</code>)과 기준 URL(예: <code>https://shop.example.com</code>)을 입력합니다.</li></ol><h3 id="_2단계-브라우저-녹화-시작" tabindex="-1">2단계: 브라우저 녹화 시작 <a class="header-anchor" href="#_2단계-브라우저-녹화-시작" aria-label="Permalink to “2단계: 브라우저 녹화 시작”">​</a></h3><ol><li>좌측 메뉴에서 <strong>&#39;시나리오&#39;</strong> ➔ <strong>&#39;새로운 시나리오&#39;</strong>를 클릭합니다.</li><li>녹화 브라우저(Chrome)와 뷰포트 크기(1920x1080)를 선택한 후 <strong>&#39;녹화 시작&#39;</strong> 버튼을 누릅니다.</li><li>생성된 브라우저 창에서 다음 동작을 수행합니다: <ul><li>검색창 클릭 후 검색어(<code>무선 키보드</code>) 입력</li><li>검색 버튼 클릭</li><li>검색 결과 목록에서 첫 번째 상품 클릭</li></ul></li><li>녹화 창 상단의 <strong>&#39;녹화 종료&#39;</strong>를 클릭하여 시나리오를 저장합니다.</li></ol><h3 id="_3단계-검증-조건-assertion-추가" tabindex="-1">3단계: 검증 조건(Assertion) 추가 <a class="header-anchor" href="#_3단계-검증-조건-assertion-추가" aria-label="Permalink to “3단계: 검증 조건(Assertion) 추가”">​</a></h3><ol><li>저장된 시나리오 목록에서 방금 생성한 시나리오를 엽니다.</li><li>마지막 상품 상세 페이지 이동 스텝을 우클릭하고 <strong>&#39;검증 조건 추가&#39; ➔ &#39;요소 노출 검증&#39;</strong>을 선택합니다.</li><li>화면상의 <strong>&#39;장바구니 담기&#39;</strong> 버튼 요소를 클릭하여 검증 대상으로 등록합니다.</li></ol><h3 id="_4단계-playwright-mcp로-테스트-실행" tabindex="-1">4단계: Playwright MCP로 테스트 실행 <a class="header-anchor" href="#_4단계-playwright-mcp로-테스트-실행" aria-label="Permalink to “4단계: Playwright MCP로 테스트 실행”">​</a></h3><ol><li>우측 상단의 <strong>&#39;시나리오 실행&#39;</strong> 버튼을 클릭합니다.</li><li>실행 옵션에서 <strong>&#39;헤드리스 모드(Headless)&#39;</strong> 및 <strong>&#39;비디오 저장(Save Video)&#39;</strong>을 체크하고 <strong>&#39;실행&#39;</strong>을 누릅니다.</li><li>실행이 완료되면 <strong>&#39;대시보드&#39;</strong> 메뉴로 이동하여 실행 소요 시간, 각 스텝별 통과 상태 및 녹화된 비디오(MP4)를 확인합니다.</li></ol><hr><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to “다음 단계”">​</a></h2><ul><li><a href="./scenario-create">시나리오 녹화 및 에디터 상세 가이드</a> - 대기 조건, 복구 스크립트 설정</li><li><a href="./dataset">데이터셋 관리</a> - Excel을 활용한 대량 파라미터 테스트</li><li><a href="./mcp-and-cicd">MCP 프로토콜 및 CI/CD 연동</a> - GitHub Actions 및 Jenkins 파이프라인 연동</li></ul>`,23)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
